#!/usr/bin/env node
import { startServer } from '@vurb/core';
import { f } from './vurb.js';
// Explicit imports for edge deployment (V8 isolates have no fs.readdir)
import licenseAudit from './agents/license/audit.tool.js';
import licenseCheck from './agents/license/check.tool.js';
import licensePolicy from './agents/license/policy.tool.js';
import licenseTree from './agents/license/tree.tool.js';
async function main() {
    const registry = f.registry();
    registry.register(licenseAudit);
    registry.register(licenseCheck);
    registry.register(licensePolicy);
    registry.register(licenseTree);
    await startServer({
        name: 'oss-license-auditor',
        version: '1.0.0',
        registry,
    });
}
main().catch(console.error);
